INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (60, N'Vize nasıl alınır?', N'Robot', N'Vize süreci genelde şu adımlarla ilerler: 1) Gideceğin ülkenin vize türünü belirle (turistik/ticari/öğrenci), 2) Randevu al, 3) Evrakları hazırla, 4) Başvuru merkezi veya konsolosluğa teslim et, 5) Biyometri işlemlerini tamamla, 6) Sonucu takip et.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (61, N'Vize isteyen ülkeler hangileri?', N'Robot', N'Türkiye Cumhuriyeti pasaportu için vize gereksinimi ülkeye ve pasaport tipine göre değişir. Schengen ülkeleri, ABD, Birleşik Krallık ve Kanada gibi birçok ülke başvuru ister. Güncel liste için ilgili ülkenin resmi konsolosluk sayfasını kontrol etmelisin.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (62, N'Schengen vizesi için gerekli evraklar nelerdir?', N'Robot', N'Schengen için yaygın evraklar: Pasaport, biyometrik fotoğraf, başvuru formu, seyahat sağlık sigortası, uçuş/konaklama rezervasyonu, banka dökümü, çalışma/öğrenci belgeleri, nüfus kayıt örneği ve varsa davetiye.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (63, N'Vize için banka hesabında ne kadar para olmalı?', N'Robot', N'Net tutar ülkeye ve seyahat süresine göre değişir. Genel yaklaşım günlük harcama + konaklama + ulaşım bütçesini karşılayacak bakiye göstermektir. Konsolosluklar düzenli gelir ve hesap hareketine de bakar.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (64, N'Vize ücretleri ne kadar?', N'Robot', N'Vize ücretleri ülkeye, vize türüne ve yaş grubuna göre değişir. Schengen kısa süreli başvurularda konsolosluk harcı + başvuru merkezi hizmet bedeli alınır. Güncel tutar için resmi konsolosluk ve aracı kurum sayfasını kontrol etmelisin.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (65, N'ABD vizesi için hangi evraklar gerekli?', N'Robot', N'ABD turist vizesinde DS-160 formu, pasaport, biyometrik fotoğraf, randevu onayı, ödeme dekontu ve seyahat planı temel belgelerdir. Ek olarak gelir/iş/öğrenci belgeleri ve Türkiye''ye geri dönüş bağını gösteren evraklar faydalıdır.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (66, N'İngiltere vizesi için evraklar neler?', N'Robot', N'İngiltere ziyaretçi vizesinde online form, pasaport, finansal belgeler (banka dökümü/maaş), konaklama ve uçuş planı, iş/öğrenci belgeleri ve varsa sponsor evrakları gerekir.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (67, N'Vize reddi olursa ne yapmalıyım?', N'Robot', N'Ret gerekçesini dikkatle inceleyip eksik/uyumsuz noktaları düzeltmelisin. Gerekirse yeni ve güçlendirilmiş evrakla tekrar başvuru yapılır. Bazı ülkelerde itiraz hakkı da bulunur.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (68, N'Vize kaç günde çıkar?', N'Robot', N'Sonuç süresi ülkeye, döneme ve başvuru yoğunluğuna göre değişir. Turistik vizelerde genelde birkaç iş günü ile birkaç hafta arası sürer. Seyahat tarihinden önce erken başvuru önerilir.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (69, N'Vize randevusu nasıl alınır?', N'Robot', N'Randevu, ilgili ülkenin resmi vize portalı veya yetkili başvuru merkezi üzerinden alınır. Ülke, vize türü ve şehir seçilerek uygun tarih/saat belirlenir; onay belgesi saklanmalıdır.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (70, N'Yemek ücretleri ne olur?', N'Robot', N'Yemek bütçesi şehir ve ülkeye göre değişir. Ortalama hesapla: ekonomik öğün, orta segment restoran ve premium restoran olarak 3 seviyede plan yap. İstersen gideceğin ülkeye göre günlük net aralık çıkarabilirim.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (71, N'Otel ücretleri ne kadar olur?', N'Robot', N'Otel ücretleri sezona ve bölgeye göre değişir. Genel plan için gecelik düşük/orta/yüksek segment ayırıp merkez-çevre fiyat farkını birlikte hesaplamak en sağlıklı yöntemdir.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (72, N'Ulaşım ücretleri ne kadar olur?', N'Robot', N'Ulaşımda şehir içi kart, tek biniş, havalimanı transferi ve şehirler arası bilet kalemlerini ayrı hesaplamak gerekir. Böylece toplam maliyet daha net çıkar.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (73, N'Yemek otel ulaşım toplam ne kadar tutar?', N'Robot', N'Toplam bütçe için 3 ana kalem öneririm: konaklama + yeme-içme + ulaşım. Gün sayısı ve şehir bilgisi verirsen düşük/orta/yüksek senaryoda günlük ve toplam maliyeti net çıkarabilirim.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (74, N'Günlük yemek bütçesi ne kadar olmalı?', N'Robot', N'Günlük yemek bütçesini kahvaltı-öğle-akşam ve atıştırmalık olarak ayrı düşünmek gerekir. Ekonomik, orta ve yüksek bütçe senaryosuyla daha gerçekçi sonuç alırsın.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (75, N'Ulaşım kartı mı taksi mi daha uygun?', N'Robot', N'Kısa ve çoklu duraklı rotalarda toplu taşıma kartı çoğu zaman daha ekonomiktir. Gece geç saat veya kapıdan kapıya ihtiyaçta taksi/uygulama araçları avantaj sağlar.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (76, N'İtalya''da metro otobüs tramvay nasıl kullanılır?', N'Robot', N'İtalya''da şehir içi ulaşımda metro, otobüs ve tramvay için şehirlerin toplu taşıma ağını tek uygulamadan takip etmek faydalıdır. Biletinizi araç öncesi alın/aktive edin ve denetim için saklayın.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (77, N'İtalya toplu taşıma biletleri nasıl alınır?', N'Robot', N'Biletleri metro istasyon otomatları, tabacchi noktaları veya resmi mobil uygulamalardan alabilirsiniz. Tek biniş yanında günlük/48-72 saatlik kartlar kısa gezilerde daha avantajlı olabilir.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (78, N'İtalya''da metro otobüs tramvay bilet ücretleri ne kadar?', N'Robot', N'Ücretler şehre göre değişir. Genelde tek bilet + süreli kart (24/48/72 saat) seçenekleri bulunur. En doğru fiyat için bulunduğunuz şehrin resmi toplu taşıma sitesini kontrol etmelisiniz.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (79, N'Roma''da metro otobüs tramvay için hangi bilet alınmalı?', N'Robot', N'Roma''da gün içi yoğun gezi planında 24 saatlik veya çoklu biniş seçenekleri pratik olur. Az duraklı planlarda tek bilet yeterli olabilir; biletinizi ilk kullanımda doğrulamayı unutmayın.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (80, N'Yurt dışında telefon nasıl kullanılır?', N'Robot', N'Yurt dışında telefon için üç temel seçenek var: operatör roaming paketi, yerel SIM kart veya eSIM. Kısa seyahatte eSIM pratik, uzun konaklamada yerel SIM genelde daha ekonomik olur.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (81, N'Mobil internet ücretleri ne kadar olur?', N'Robot', N'Mobil internet ücretleri ülkeye ve operatöre göre değişir. Turist paketlerinde 10-30 GB aralığı için genelde 10-35€ bandı görülür; havaalanı satışları merkez mağazalara göre biraz daha pahalı olabilir.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (82, N'SIM kart nereden alınır?', N'Robot', N'SIM kartı havaalanı kiosklarından, şehir merkezindeki operatör mağazalarından veya eSIM uygulamalarından alabilirsiniz. Pasaport gereksinimi ülkeye göre değişebilir; satın almadan önce kimlik şartlarını kontrol edin.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (83, N'Roaming mi yerel SIM mi daha uygun?', N'Robot', N'Genelde kısa ve düşük kullanımda roaming paketi pratik olur; veri tüketimi yüksek veya uzun seyahatlerde yerel SIM/eSIM daha uygun maliyet sağlar. Karar için gün sayısı ve internet ihtiyacını birlikte değerlendirmek gerekir.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (84, N'İndirim dönemleri ne zaman olur?', N'Robot', N'İndirim dönemleri ülkeden ülkeye değişse de genelde sezon sonlarında (kış/yaz) ve özel kampanya haftalarında yoğunlaşır. Seyahat tarihini yazarsan daha net alışveriş dönemi önerisi verebilirim.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (85, N'Destinasyonda uygun mağazalar nerede olur?', N'Robot', N'Uygun mağazalar için merkez alışveriş caddeleri + outlet bölgeleri birlikte değerlendirilmelidir. Merkezde yeni sezon, outlette önceki sezon ürünleri daha avantajlı bulunur.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (86, N'Outlet mi merkez mağaza mı daha uygun?', N'Robot', N'Fiyat odaklı alışverişte outlet genelde daha uygundur; yeni sezon ve güncel koleksiyon için merkez mağazalar öne çıkar. En iyi sonuç için ikisini aynı gün planlamak faydalı olur.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (87, N'Tax free oranları nedir?', N'Robot', N'Tax free oranları ülkeye, ürün grubuna ve iade sağlayıcı kuruma göre değişir. Net oran için alışveriş yapacağın ülkedeki güncel resmi tax free kurallarını ve mağaza iade oranını kontrol etmelisin.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (88, N'Hangi ülkelerde tax free var?', N'Robot', N'Birçok ülkede turistlere yönelik tax free iadesi bulunur; ancak minimum alışveriş tutarı, ürün kapsamı ve iade yöntemi farklıdır. Gideceğin ülkeyi yazarsan temel kuralları özetleyebilirim.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (89, N'Tax free nasıl alınır?', N'Robot', N'Genelde tax free anlaşmalı mağazadan alışveriş yapıp pasaport bilgisiyle form doldurulur. Çıkış noktasında gümrük onayı alınır ve iade nakit veya karta yapılır.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (90, N'Tax free için gerekli evraklar neler?', N'Robot', N'Genelde pasaport, tax free formu ve alışveriş faturası gerekir. Ürünü kullanılmamış halde göstermen istenebilir; ülkeye göre ek belge talebi olabilir.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (91, N'Seyahat çantasında neler olmalı?', N'Robot', N'Seyahat çantası için temel liste: pasaport/kimlik, bilet ve rezervasyon çıktıları, ilaçlar, şarj cihazı-powerbank, kişisel bakım ürünleri (100 ml kuralına uygun), yedek kıyafet, rahat ayakkabı, adaptör ve küçük ilk yardım seti.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (92, N'Uçak için kabin bavul ölçüsü nedir?', N'Robot', N'Kabin bavul ölçüsü havayoluna göre değişir; yaygın ölçü 55x40x20 cm civarındadır. Kesin ölçü ve kilo limitini bilet aldığınız havayolunun resmi kurallarından kontrol etmelisiniz.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (93, N'Uçak bagaj ücreti ne kadar?', N'Robot', N'Bagaj ücreti havayolu, rota, sınıf ve satın alma zamanına göre değişir. Online erken bagaj satın alma genelde havaalanına göre daha uygun olur.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (94, N'Ekstra bavul ücreti nasıl hesaplanır?', N'Robot', N'Ekstra bavul ücreti adet, kilo aşımı ve uçuş bölgesine göre hesaplanır. En doğru tutar için havayolunun bagaj hesaplama ekranında PNR ile kontrol önerilir.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (95, N'Çantam çalındı ne yapmalıyım?', N'Robot', N'Önce en yakın polis merkezine gidip tutanak al, kartlarını hemen bloke et, telefon/e-posta güvenliğini güncelle ve konaklama yerine bilgi ver. Çok dilli cümleler: EN: My bag was stolen. IT: Mi hanno rubato la borsa. AR: تمت سرقة حقيبتي.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (96, N'Pasaportum çalındı ne yapmalıyım?', N'Robot', N'Polis tutanağı al, en yakın Türkiye Cumhuriyeti temsilciliğiyle iletişime geç ve geçici seyahat belgesi sürecini başlat. Çok dilli cümleler: EN: My passport was stolen. IT: Mi hanno rubato il passaporto. AR: تمت سرقة جواز سفري.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (97, N'Otel pansiyon airbnb ücretleri ne kadar olur?', N'Robot', N'Konaklama maliyetinde otel genelde hizmet seviyesiyle birlikte daha yüksek olabilir; pansiyon daha ekonomik seçenek sunar; Airbnb ise konum ve sezona göre değişkenlik gösterir. Ülke, şehir ve tarih verirsen net düşük/orta/yüksek fiyat aralığı çıkarabilirim.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (98, N'Hangi ülkede otel pansiyon airbnb daha uygun?', N'Robot', N'Konaklama uygunluğu ülkeye, şehre ve sezona göre değişir. Genel olarak merkez dışı bölgelerde pansiyon ve bazı Airbnb seçenekleri daha uygun olabilir. Gideceğin ülke/destinasyonu yazarsan karşılaştırmalı tablo hazırlayabilirim.', N'2026-10-25 06:25:13')
INSERT INTO [dbo].[DemoChatServices] ([Id], [Input], [SessionId], [Reply], [CreatedAt]) VALUES (99, N'Destinasyon için otel pansiyon airbnb karşılaştırması yap', N'Robot', N'Destinasyon bazlı karşılaştırmada otel, pansiyon ve Airbnb için gecelik ortalama, konum avantajı, iptal esnekliği ve ulaşım maliyeti birlikte değerlendirilmelidir. Şehir adı ve gün sayısını yaz, net tablo çıkarayım.', N'2026-10-25 06:25:13')
